	`),!OB(Z,"entity_dependencies"))return;Z.exec("DROP TRIGGER IF EXISTS trg_entity_dependencies_related_to_reason_insert"),Z.exec("DROP TRIGGER IF EXISTS trg_entity_dependencies_related_to_reason_update"),Z.exec("DROP TRIGGER IF EXISTS trg_entity_dependencies_audit_insert"),Z.exec("DROP TRIGGER IF EXISTS trg_entity_dependencies_audit_update"),Z.exec("DROP TRIGGER IF EXISTS trg_entity_dependencies_audit_delete"),Z.exec(`
